// Minimal texts for CLIENT components (error screen, "loading"). Importing `dict` in a client component would bring the dictionaries
// of all languages to the browser; this file carries only the six phrases they need (generated by `scripts/translate-site.mjs cliente`).
import texts from '@/i18n/client.json'
import { isReady, DEFAULT, type Ready } from '@/lib/i18n-base'

export type ClientTexts = (typeof texts)['pt']

export function pathLanguage(path: string): Ready {
  const segment = path.split('/')[1] ?? ''
  return isReady(segment) ? segment : DEFAULT
}
export const clientTexts = (lang: Ready): ClientTexts => (texts as Record<Ready, ClientTexts>)[lang]
